import React, { useState } from 'react';
import { profiles, categories } from '../data/products';
import ProductCard from './ProductCard';
import { Filter, Search } from 'lucide-react';

const Products = () => {
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState('name');

  const filteredProfiles = profiles.filter(profile => {
    const matchesCategory = selectedCategory === 'all' || profile.category === selectedCategory;
    const matchesSearch = profile.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         profile.nameEn.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         profile.description.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const sortedProfiles = [...filteredProfiles].sort((a, b) => {
    switch (sortBy) {
      case 'age-low':
        return a.age - b.age;
      case 'age-high':
        return b.age - a.age;
      case 'rating':
        return b.rating - a.rating;
      case 'name':
      default:
        return a.name.localeCompare(b.name);
    }
  });

  return (
    <section id="products" className="py-20 bg-gray-50">
      <div className="container mx-auto px-4">
        <div className="text-center mb-12">
          <h2 className="text-4xl font-bold text-cannabis-green mb-4">
            โปรไฟล์ของเรา
          </h2>
          <p className="text-xl text-gray-600 max-w-2xl mx-auto">
            คนที่คัดสรรมาอย่างพิถีพิถัน เพื่อให้แน่ใจว่าคุณจะได้พบคนที่เหมาะสมที่สุด
          </p>
        </div>

        {/* Filters and Search */}
        <div className="bg-white rounded-xl shadow-md p-6 mb-8">
          <div className="grid md:grid-cols-3 gap-4">
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
              <input
                type="text"
                placeholder="ค้นหาโปรไฟล์..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-cannabis-green"
              />
            </div>

            {/* Category Filter */}
            <div className="relative">
              <Filter className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
              <select
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-cannabis-green appearance-none"
              >
                {categories.map(category => (
                  <option key={category.id} value={category.id}>
                    {category.name}
                  </option>
                ))}
              </select>
            </div>

            {/* Sort */}
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-cannabis-green"
            >
              <option value="name">เรียงตามชื่อ</option>
              <option value="age-low">อายุ: น้อย-มาก</option>
              <option value="age-high">อายุ: มาก-น้อย</option>
              <option value="rating">คะแนนสูงสุด</option>
            </select>
          </div>
        </div>

        {/* Profiles Grid */}
        {sortedProfiles.length > 0 ? (
          <div className="grid md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {sortedProfiles.map(profile => (
              <ProductCard key={profile.id} profile={profile} />
            ))}
          </div>
        ) : (
          <div className="text-center py-12">
            <div className="text-gray-400 mb-4">
              <Filter size={48} className="mx-auto" />
            </div>
            <h3 className="text-xl font-semibold text-gray-600 mb-2">
              ไม่พบโปรไฟล์ที่ค้นหา
            </h3>
            <p className="text-gray-500">
              ลองเปลี่ยนเงื่อนไขการค้นหาหรือกรองข้อมูล
            </p>
          </div>
        )}

        {/* Profile Stats */}
        <div className="mt-12 bg-cannabis-green rounded-xl p-8 text-white">
          <div className="grid md:grid-cols-4 gap-6 text-center">
            <div>
              <div className="text-3xl font-bold mb-2">{profiles.length}</div>
              <p className="text-cannabis-accent">โปรไฟล์ทั้งหมด</p>
            </div>
            <div>
              <div className="text-3xl font-bold mb-2">
                {profiles.filter(p => p.online).length}
              </div>
              <p className="text-cannabis-accent">ออนไลน์อยู่</p>
            </div>
            <div>
              <div className="text-3xl font-bold mb-2">
                {Math.round(profiles.reduce((acc, p) => acc + p.rating, 0) / profiles.length * 10) / 10}
              </div>
              <p className="text-cannabis-accent">คะแนนเฉลี่ย</p>
            </div>
            <div>
              <div className="text-3xl font-bold mb-2">
                {profiles.reduce((acc, p) => acc + p.reviews, 0).toLocaleString()}
              </div>
              <p className="text-cannabis-accent">รีวิวทั้งหมด</p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Products;
